import fitz

# Check what the proper on-state values should be for checkboxes
doc = fitz.open('/root/sc100-blank.pdf')

for page in doc:
    for widget in page.widgets():
        if 'Checkbox' in widget.field_name:
            # Get the widget's appearance states
            print(f"{widget.field_name}")
            try:
                print(f"  on_state: {widget.on_state()}")  # What value turns it on
            except Exception as e:
                print(f"  Error: {e}")

doc.close()
